7	// The public /#/join waitlist. One page that becomes two: a wide viewport gets
8	// the "constellation" layout (copy settled in the lower third), a narrow one
9	// gets the "drift" layout (headline up top, capture at the bottom). Both ride
10	// the same drifting star field. The 620px breakpoint drives layout and copy
11	// together so they never disagree.
12	type Mode = "desktop" | "phone";
13	type Status = "idle" | "submitting" | "joined";
14	
15	const BREAKPOINT = 620;
16	
17	function initialMode(): Mode {
18	  return typeof window !== "undefined" && window.innerWidth >= BREAKPOINT
19	    ? "desktop"
20	    : "phone";
21	}
22	
23	// Copy shifts with the layout; each side keeps the wording it was designed with.
24	const COPY: Record<Mode, {
25	  headline: string;
26	  sub: string;
27	  cta: string;
28	  fine: string;
29	}> = {
30	  desktop: {
31	    headline: "Your people are a constellation.",
32	    sub: "Every person you meet becomes a point of light -- and Euno keeps them from drifting away.",
33	    cta: "Join",
34	    fine: "Private beta. We add people in small groups.",
35	  },
36	  phone: {
37	    headline: "The people you meet, never lost again.",
38	    sub: "A quiet memory layer over the people of your life. Get in early.",
39	    cta: "Request access",
40	    fine: "No spam. Invites go out in waves.",
41	  },
42	};
43	
44	function CheckIcon() {
45	  return (
46	    <svg viewBox="0 0 24 24" fill="none" stroke="#0a84ff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
47	      <path d="M20 6 9 17l-5-5" />
48	    </svg>
49	  );
50	}
