52	export function Waitlist() {
53	  const rootRef = useRef<HTMLDivElement | null>(null);
54	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
55	  const [mode, setMode] = useState<Mode>(initialMode);
56	  const [email, setEmail] = useState("");
57	  const [status, setStatus] = useState<Status>("idle");
58	  const [error, setError] = useState<string | null>(null);
59	  const join = useMutation(api.waitlist.joinWaitlist);
60	
61	  // Layout follows the page width, flipping at the same breakpoint the copy
62	  // uses so the two stay in step.
63	  useEffect(() => {
64	    const root = rootRef.current;
65	    if (root === null) return;
66	    const observer = new ResizeObserver(([entry]) => {
67	      setMode(entry.contentRect.width >= BREAKPOINT ? "desktop" : "phone");
68	    });
69	    observer.observe(root);
70	    return () => observer.disconnect();
71	  }, []);
72	
73	  // The drifting star field. Lives for the component's lifetime and tears
74	  // down its animation frame on unmount; a still frame under reduced motion.
75	  useEffect(() => {
76	    const canvas = canvasRef.current;
77	    if (canvas === null) return;
78	    return startDrift(canvas);
79	  }, []);
80	
81	  async function onSubmit(event: FormEvent) {
82	    event.preventDefault();
83	    setError(null);
84	    if (!isValidEmail(email)) {
85	      setError("Enter a valid email address.");
86	      return;
87	    }
88	    setStatus("submitting");
89	    try {
90	      await join({ email, source: mode });
91	      setStatus("joined");
92	    } catch (err) {
93	      setStatus("idle");
94	      // ConvexError carries our own server message; anything else is a network
95	      // or unexpected failure the person can just retry.
96	      setError(
97	        err instanceof ConvexError && typeof err.data === "string"
98	          ? err.data
99	          : "Something went wrong. Please try again.",
100	      );
101	    }
102	  }
103	
104	  const copy = COPY[mode];
105	
106	  return (
107	    <div ref={rootRef} className="waitlist" data-mode={mode}>
108	      <canvas ref={canvasRef} className="wl-sky" aria-hidden="true" />
109	      {/* Existing beta users reach the Clerk flow here; the "#/sign-in" hash
110	          routes App to sign-in without leaving this page for strangers. */}
111	      <a className="wl-signin" href="#/sign-in">
112	        Sign in
113	      </a>
114	      <div className="wl-content">
115	        {status === "joined" ? (
116	          <div className="wl-joined" role="status">
117	            <div className="wl-check" aria-hidden="true">
118	              <CheckIcon />
119	            </div>
120	            <p className="wl-checkline">You are on the list.</p>
121	            <p className="wl-sub wl-joined-sub">
122	              We will reach out when your invite is ready. Thanks for your patience.
123	            </p>
124	          </div>
125	        ) : (
126	          <>
127	            <div className="wl-top">
128	              <span className="wl-eyebrow">Euno -- private beta</span>
129	              <h1 className="wl-headline">{copy.headline}</h1>
130	            </div>
131	            <div className="wl-bottom">
132	              <p className="wl-sub">{copy.sub}</p>
133	              <form className="wl-form" onSubmit={onSubmit} noValidate>
134	                <input
135	                  className="wl-field"
136	                  type="email"
137	                  inputMode="email"
138	                  autoComplete="email"
139	                  placeholder="Your email"
140	                  aria-label="Email address"
141	                  value={email}
142	                  onChange={(event) => {
143	                    setEmail(event.target.value);
144	                    if (error !== null) setError(null);
145	                  }}
146	                />
147	                <button className="wl-go" type="submit" disabled={status === "submitting"}>
148	                  {status === "submitting" ? "Joining" : copy.cta}
149	                </button>
150	              </form>
151	              {error !== null ? (
152	                <p className="wl-error" role="alert">{error}</p>
153	              ) : (
154	                <p className="wl-fine">{copy.fine}</p>
155	              )}
156	            </div>
157	          </>
158	        )}
159	      </div>
160	    </div>
161	  );
162	}
