164	type Star = {
165	  x: number;
166	  y: number;
167	  size: number;
168	  base: number;
169	  sp: number;
170	  tw: number;
171	  hot: boolean;
172	};
173	
174	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
175	// stars move faster. Returns its own teardown. Ported from the approved
176	// prototype so the shipped page matches it exactly.
177	function startDrift(canvas: HTMLCanvasElement): () => void {
178	  const ctx = canvas.getContext("2d");
179	  if (ctx === null) return () => {};
180	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
181	  let w = 0;
182	  let h = 0;
183	  let raf = 0;
184	  let stars: Star[] = [];
185	
186	  function size() {
187	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
188	    w = canvas.clientWidth;
189	    h = canvas.clientHeight;
190	    canvas.width = w * dpr;
191	    canvas.height = h * dpr;
192	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
193	  }
194	
195	  function build() {
196	    size();
197	    const count = Math.min(300, Math.floor((w * h) / 3600));
198	    stars = [];
199	    for (let i = 0; i < count; i++) {
200	      const depth = Math.random();
201	      stars.push({
202	        x: Math.random() * w,
203	        y: Math.random() * h,
204	        size: 0.5 + depth * 1.6,
205	        base: 0.1 + depth * 0.45,
206	        sp: 0.05 + depth * 0.22,
207	        tw: Math.random() * 6.28,
208	        hot: Math.random() < 0.04,
209	      });
210	    }
211	  }
212	
213	  function frame(t: number) {
214	    const time = t / 1000;
215	    ctx!.clearRect(0, 0, w, h);
216	    for (const s of stars) {
217	      if (!reduce) {
218	        s.x += s.sp;
219	        if (s.x > w + 2) s.x = -2;
220	      }
221	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
222	      ctx!.beginPath();
223	      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
224	      if (s.hot) {
225	        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
226	        ctx!.shadowColor = "rgba(10,132,255,.8)";
227	        ctx!.shadowBlur = 6;
228	      } else {
229	        ctx!.fillStyle = `rgba(255,255,255,${s.base * tw})`;
230	        ctx!.shadowBlur = 0;
231	      }
232	      ctx!.fill();
233	    }
234	    ctx!.shadowBlur = 0;
235	    if (!reduce) raf = requestAnimationFrame(frame);
236	  }
237	
238	  function onResize() {
239	    build();
240	    if (reduce) frame(0);
241	  }
242	
243	  build();
244	  if (reduce) frame(0);
245	  else raf = requestAnimationFrame(frame);
246	  window.addEventListener("resize", onResize);
247	
248	  return () => {
249	    cancelAnimationFrame(raf);
250	    window.removeEventListener("resize", onResize);
251	  };
252	}
